// ─── File: AuthOffloadDemo.java ───
// Offload JWT verification: cached keys, dedicated auth tier, RSA vs ECDSA cost.
package com.bank.gateway.demo;

import java.util.logging.*;

public class AuthOffloadDemo {
    private static final Logger log = Logger.getLogger("AuthOffload");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new AoLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int requests = 20;

        log.info("=== Baseline: fetch key + verify PER request (RSA) ===");
        KeyCache sharedKeys = new KeyCache();
        PerRequestAuthGateway baseline = new PerRequestAuthGateway(sharedKeys, "RSA");
        for (int i = 0; i < requests; i++) baseline.handle("jwt-rajesh");
        log.info(() -> "Baseline networkKeyFetches=" + baseline.getKeyFetches()
                + " cpuCost=" + baseline.getCpuCost());

        log.info("=== Local verification with CACHED key (RSA) ===");
        LocalVerifyGateway local = new LocalVerifyGateway(new KeyCache(), "RSA");
        for (int i = 0; i < requests; i++) local.handle("jwt-rajesh");
        log.info(() -> "LocalVerify(RSA) networkKeyFetches=" + local.getKeyFetches()
                + " cpuCost=" + local.getCpuCost());

        log.info("=== Local verification with CACHED key (ECDSA — cheaper verify) ===");
        LocalVerifyGateway localEc = new LocalVerifyGateway(new KeyCache(), "ECDSA");
        for (int i = 0; i < requests; i++) localEc.handle("jwt-rajesh");
        log.info(() -> "LocalVerify(ECDSA) networkKeyFetches=" + localEc.getKeyFetches()
                + " cpuCost=" + localEc.getCpuCost());

        log.info("=== Dedicated auth tier: verify ONCE, inner trusts context token ===");
        AuthTier authTier = new AuthTier(new KeyCache(), "ECDSA");
        InnerService inner = new InnerService();
        ContextToken ctx = authTier.verifyOnceAndIssue("jwt-rajesh"); // heavy verify once
        for (int i = 0; i < requests; i++) inner.handle(ctx);          // cheap trust-check only
        log.info(() -> "AuthTier heavyVerifications=" + authTier.getVerifications()
                + " innerCheapChecks=" + inner.getChecks());
    }
}

// ─── Would be in auth/KeyCache.java ───
class KeyCache {
    private static final Logger log = Logger.getLogger("AuthOffload");
    private String cachedKey; private int fetches = 0;
    // Fetch JWKS once over the network, then serve from cache (refresh on rotation).
    String getKey() {
        if (cachedKey == null) { cachedKey = fetchFromJwks(); fetches++; }
        return cachedKey;
    }
    String getKeyAlwaysFetch() { fetches++; return fetchFromJwks(); } // baseline anti-pattern
    private String fetchFromJwks() { sleep(15); return "public-key"; } // network round trip
    int getFetches() { return fetches; }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

// ─── Would be in auth/TokenVerifier.java ───
class TokenVerifier {
    // Relative CPU cost units: RSA verify modeled heavier than ECDSA verify.
    static final int RSA_COST = 5;
    static final int ECDSA_COST = 2;
    private final String algorithm;
    TokenVerifier(String algorithm) { this.algorithm = algorithm; }
    int verify(String token, String key) {
        int cost = "ECDSA".equals(algorithm) ? ECDSA_COST : RSA_COST; // ECDSA cheaper per verify
        return cost; // return cpu cost consumed
    }
}

// ─── Would be in gateway/PerRequestAuthGateway.java (ANTI-PATTERN) ───
class PerRequestAuthGateway {
    private final KeyCache keys; private final TokenVerifier verifier;
    private int cpuCost = 0;
    PerRequestAuthGateway(KeyCache keys, String alg) { this.keys = keys; this.verifier = new TokenVerifier(alg); }
    void handle(String token) {
        String key = keys.getKeyAlwaysFetch();  // BAD: network per request
        cpuCost += verifier.verify(token, key);  // crypto per request
    }
    int getKeyFetches() { return keys.getFetches(); }
    int getCpuCost() { return cpuCost; }
}

// ─── Would be in gateway/LocalVerifyGateway.java (FIX 1) ───
class LocalVerifyGateway {
    private final KeyCache keys; private final TokenVerifier verifier;
    private int cpuCost = 0;
    LocalVerifyGateway(KeyCache keys, String alg) { this.keys = keys; this.verifier = new TokenVerifier(alg); }
    void handle(String token) {
        String key = keys.getKey();              // GOOD: cached key, no network after first
        cpuCost += verifier.verify(token, key);  // still verify locally, but cheaply
    }
    int getKeyFetches() { return keys.getFetches(); }
    int getCpuCost() { return cpuCost; }
}

// ─── Would be in auth/ContextToken.java ───
class ContextToken {
    final String user; final boolean verified;
    ContextToken(String user, boolean verified) { this.user = user; this.verified = verified; }
}

// ─── Would be in auth/AuthTier.java (FIX 2) ───
class AuthTier {
    private final KeyCache keys; private final TokenVerifier verifier; private int verifications = 0;
    AuthTier(KeyCache keys, String alg) { this.keys = keys; this.verifier = new TokenVerifier(alg); }
    // Heavy verify happens ONCE here; inner services trust the issued context token.
    ContextToken verifyOnceAndIssue(String jwt) {
        verifier.verify(jwt, keys.getKey()); verifications++;
        return new ContextToken("rajesh", true);
    }
    int getVerifications() { return verifications; }
}

// ─── Would be in service/InnerService.java ───
class InnerService {
    private int checks = 0;
    // Only a cheap trust-check of the context token — no crypto, no network.
    void handle(ContextToken ctx) { if (ctx.verified) checks++; }
    int getChecks() { return checks; }
}

